  const plain = text.replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ');
  const acct = plain.match(/Ad account\s*:\s*(.*?)\s*\(\s*(\d{6,})\s*\)/i);
  const adAccount = acct ? `${acct[1]} ${acct[2]}` : '';
  const from = header(j, 'From') || j.from?.text || j.from?.value || '';
  const subject = header(j, 'Subject') || j.subject || '';
  const base = {
    messageId: j.id || j.messageId || j.threadId || '',
    threadId: j.threadId || '',
    from, subject, adAccount,
    emailDate: j.internalDate || header(j, 'Date') || j.date || new Date().toISOString()
  };
  // 1) Real spreadsheet attachments
  let hasFile = false;
  for (const [property, binary] of Object.entries(item.binary || {})) {
    const fileName = binary.fileName || property;
    const mime = binary.mimeType || '';
    const isSheet = /\.(csv|xlsx?|xlsm)$/i.test(fileName) || /csv|spreadsheet|excel|sheet/i.test(mime);
    if (!isSheet) continue;
    out.push({ json: { ...base, fileName, sourceProperty: property }, binary: { data: binary } });
    hasFile = true;
  }
}
return out;

