const KEY = ["Date"];
const brands = new Map();
for (const { json: r } of $input.all()) {
  const { Brand_Name, Report_Sheet_ID, Weekly_Report_Sheet_ID, messageId, Subject, reportLevel, Raw_Sheet_ID, ...row } = r;
  if (!['Spend','Impressions','Reach','Clicks','Profile_Visits','Follows','Adds_to_Cart','Initiate_Checkout','Purchases','Purchases_Value'].some(k => Number(row[k]) > 0)) continue; // skip ads with no activity
  if (!brands.has(Raw_Sheet_ID)) brands.set(Raw_Sheet_ID, new Map());
  // last row wins inside one run, so duplicates within a file collapse
  brands.get(Raw_Sheet_ID).set(KEY.map(k => row[k]).join('|'), row);
}
return [...brands].map(([Raw_Sheet_ID, rows]) => ({ json: { Raw_Sheet_ID, rows: [...rows.values()] } }));

